import json,hashlib,collections
from pathlib import Path
def raw(path):
    p=Path(path); b=p.read_bytes()
    return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'excerpt':b.decode(errors='replace')[-4096:]}

def group(prefix,family,baseline):
    path=Path(f'work/parallel-{prefix}-{family}.json'); data=json.loads(path.read_text())
    prior={Path(r['fixture']).name:r['status'] for r in json.loads(Path(baseline).read_text())['results']}
    rows=data['results']; current={Path(r['fixture']).name:r['status'] for r in rows}
    for row in rows:
        row['fixture']=Path(row['fixture']).name
        observation=row.get('observation',{}).get('Ok',{})
        for stream in ['stdout','stderr']:
            value=observation.get(stream)
            if isinstance(value,list):
                b=bytes(value); observation[stream]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'excerpt':b[:4096].decode(errors='replace')}
    return {'counts':dict(collections.Counter(current.values())),'inventory_hash':data['inventory_hash'],'baseline':raw(baseline),'raw':raw(path),'actual_exit':Path(str(path).removesuffix('.json')+'-exit.txt').read_text().strip(),'gained_passes':[k for k,v in current.items() if v=='pass' and prior.get(k)!='pass'],'lost_passes':[{'fixture':k,'status':v} for k,v in current.items() if v!='pass' and prior.get(k)=='pass'],'results':rows}




